/* master.mpvo.selectMasterMpVoVocReceiptVcNo */
	SELECT DOC_TYPE||SUBSTR(YEAR,3,2)||LPAD(CUR_NO,6,0)
	FROM ICOMSQMT
	WHERE COMPANY = #{st_company} AND DOC_TYPE = #{st_doc_type}

mapper.update:

/* master.mpvo.updateICOMSQMT */
	UPDATE ICOMSQMT SET 
	    YEAR = DECODE( YEAR,TO_CHAR( SYSDATE, 'YYYY'), YEAR, TO_CHAR( SYSDATE, 'YYYY' ) ) ,
	    CUR_NO = DECODE( YEAR, TO_CHAR( SYSDATE, 'YYYY' ), CUR_NO+1, 1 )
	WHERE COMPANY = #{st_company} AND DOC_TYPE = #{st_doc_type}
